import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityFilterSchema } from "@/schemas/activity";
import { getDb, sessions, organizations } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import { notify } from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { eq } from "drizzle-orm";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let detach: () => void;
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function tenantWithUsage(slug: string): Promise<Tenant> {
  const t = await createTenant(slug);
  await usageRepo.recomputeUsage(t.org.id);
  return t;
}

describe("org lifecycle", () => {
  it("delete → inert → restore", async () => {
    const t = await tenantWithUsage("life");
    const other = await tenantWithUsage("other");

    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { dueAt: "2026-01-01T00:00:00.000Z", assigneeId: t.userIds.member }),
    );
    void issue;

    const token = "tok-life-1";
    const invitee = await userRepo.insertUser({ email: "inv@x.test", name: "inv", passwordHash: "x" });
    const inv = await invitationRepo.insertInvitation(
      t.org.id,
      { orgId: t.org.id, email: "inv@x.test", role: "member", expiresInDays: 14 },
      t.userIds.owner,
      hashToken(token),
    );

    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: t.org.id, url: "https://example.com/h", eventTypes: ["issue.created"] },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(t.org.id, endpoint.id, "issue.created", "{}");

    const deleted: unknown[] = [];
    const offD = subscribe("organization.deleted", (p) => { deleted.push(p); });

    await expect(
      orgService.deleteOrganization(t.actors.admin, { orgId: t.org.id, confirmSlug: t.org.slug }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const d = await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
    expect(d.archivedAt).not.toBeNull();
    expect(deleted).toHaveLength(1);
    expect(deleted[0]).toMatchObject({ orgId: t.org.id, actorId: t.userIds.owner, slug: t.org.slug });
    offD();

    const audit = await activityRepo.listActivityForSubject(t.org.id, "organization", t.org.id);
    expect(audit.map((a) => a.action)).toContain("organization.deleted");
    expect(audit.find((a) => a.action === "organization.deleted")?.actorId).toBe(t.userIds.owner);

    await expect(
      orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    // sign-in / listing
    const principal = { userId: t.userIds.owner, email: "x", activeOrgId: null, expiresAt: "2099-01-01T00:00:00.000Z" } as never;
    await expect(resolveActorForOrg(principal, t.org.slug)).resolves.toBeNull();
    const listed = await orgService.listOrganizationsForUser(t.userIds.owner);
    expect(listed.map((o) => o.id)).toEqual([other.org.id]);

    // slug reserved
    const newOrg = await orgService.createOrganization(t.userIds.owner, { name: "Life again", slug: "life", plan: "free" });
    expect(newOrg.slug).not.toBe("life");

    // notify
    await expect(
      notify(t.org.id, "issue_assigned", [t.userIds.admin], { title: "t", body: "b", href: "/", actorId: null }),
    ).resolves.toEqual([]);

    // invitation
    await expect(invitationService.acceptInvitation(invitee.id, { token })).rejects.toBeInstanceOf(NotFoundError);
    const pending = await invitationRepo.listPendingInvitations(t.org.id);
    expect(pending.map((i) => i.id)).toContain(inv.id);

    // overdue
    const seen: string[] = [];
    const offO = subscribe("issue.overdue", (p) => { seen.push(p.orgId); });
    await runOverdueIssueJob(new Date());
    offO();
    expect(seen).not.toContain(t.org.id);

    // usage
    const before = await usageRepo.getUsage(t.org.id);
    await runUsageRollupJob(new Date());
    const after = await usageRepo.getUsage(t.org.id);
    expect(after.measuredAt).toBe(before.measuredAt);
    const ids = await usageRepo.listOrgIdsForRollup(100);
    expect(ids).not.toContain(t.org.id);

    // webhook
    await runWebhookDeliveryJob(new Date());
    const row = getDb().select().from((await import("@/server/db")).webhookDeliveries).all().find((r) => r.id === delivery.id);
    expect(row?.status).toBe("failed");

    // cleanup sweep doesn't purge within window
    await runCleanupArchivedJob(new Date(Date.now() + (DELETED_WORKSPACE_RETENTION_DAYS - 1) * DAY));
    expect(await orgRepo.findOrgById(t.org.id)).not.toBeNull();

    // restore
    const stranger = await userRepo.insertUser({ email: "s@x.test", name: "s", passwordHash: "x" });
    await expect(orgService.restoreOrganization(stranger.id, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(orgService.restoreOrganization(t.userIds.admin, t.org.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(orgService.restoreOrganization(t.userIds.owner, "01HZZZZZZZZZZZZZZZZZZZZZZZ" as never)).rejects.toBeInstanceOf(NotFoundError);

    const restoredEvents: unknown[] = [];
    const offR = subscribe("organization.restored", (p) => { restoredEvents.push(p); });
    const restored = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(restored.archivedAt).toBeNull();
    expect(restoredEvents).toHaveLength(1);
    const again = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
    expect(again.archivedAt).toBeNull();
    expect(restoredEvents).toHaveLength(1);
    offR();

    const audit2 = await activityRepo.listActivityForSubject(t.org.id, "organization", t.org.id);
    expect(audit2.map((a) => a.action)).toContain("organization.restored");

    await expect(resolveActorForOrg(principal, t.org.slug)).resolves.not.toBeNull();
    const member = await invitationService.acceptInvitation(invitee.id, { token });
    expect(member.orgId).toBe(t.org.id);

    expect(
      activityFilterSchema.safeParse({ orgId: t.org.id, action: ["organization.deleted", "organization.restored"] }).success,
    ).toBe(true);
  });

  it("window closes and purge", async () => {
    const t = await tenantWithUsage("purge");
    await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    const sess = await sessionRepo.createSession(t.userIds.admin, "hash-purge", "2099-01-01T00:00:00.000Z");
    void sess;
    getDb().update(sessions).set({ activeOrgId: t.org.id }).where(eq(sessions.tokenHash, "hash-purge")).run();

    await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date(Date.now() + DELETED_WORKSPACE_RETENTION_DAYS * DAY + 1000));
    try {
      await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    } finally {
      vi.useRealTimers();
    }
    expect(await orgRepo.findOrgById(t.org.id)).not.toBeNull();

    const result = await runCleanupArchivedJob(new Date(Date.now() + DELETED_WORKSPACE_RETENTION_DAYS * DAY + 1000));
    expect(result.failed).toBe(0);
    expect(await orgRepo.findOrgById(t.org.id)).toBeNull();

    const client = getDb().$client;
    const tables = client
      .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'")
      .all() as { name: string }[];
    for (const { name } of tables) {
      const cols = client.prepare(`PRAGMA table_info("${name}")`).all() as { name: string }[];
      if (!cols.some((c) => c.name === "org_id")) continue;
      const n = client.prepare(`SELECT count(*) as n FROM "${name}" WHERE org_id = ?`).get(t.org.id) as { n: number };
      expect(n.n, name).toBe(0);
    }
    const s = getDb().select().from(sessions).where(eq(sessions.tokenHash, "hash-purge")).get();
    expect(s?.activeOrgId).toBeNull();
    expect(await userRepo.findUserById(t.userIds.owner)).not.toBeNull();

    await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(NotFoundError);
    const reborn = await orgService.createOrganization(t.userIds.owner, { name: "Purge again", slug: "purge", plan: "free" });
    expect(reborn.slug).toBe("purge");
    void organizations;
    void issueRepo;
  });
});

